  if verbose and iteration%10==0:print('iteration',iteration,'min_eig',worst,'cuts',len(Aub),flush=True)
  if worst>=-tol:
   if verbose:print('FEASIBLE',iteration,'worst',worst,flush=True)
   return True,iteration,sol
 return None,maxiter,sol

